#[test]
#[expected_failure(abort_code = protocol::error::Err_Liquidation_CloseFactorExceeded, location = protocol::market)]
public fun liquidate_close_factor_exceeded_not_allowed() {
  let borrower = @0xBB;
  let liquidator = @0xCC;

  let mut scenario_value = test_scenario::begin(ADMIN);
  let scenario = &mut scenario_value;
  let mut clock = clock::create_for_testing(scenario.ctx());

  let (admin_cap, mut app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
      scenario, 
      &mut clock, 
      ADMIN,
  );
  let mut x_oracle = oracle_t::init_t(scenario);
  clock.set_for_testing(100 * 1000);
  x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000
  x_oracle.update_price<USDT>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1000

  let eth_coin = sui::coin::mint_for_testing<ETH>(1 * 10u64.pow(default_eth_decimal_places()), test_scenario::ctx(scenario));
  let usdt_coin = sui::coin::mint_for_testing<USDT>(1000 * 10u64.pow(default_stable_decimal_places()), test_scenario::ctx(scenario));

  scenario.next_tx(borrower);
  let obligation_owner_cap = open_obligation_t::open_obligation_t<MainMarket>(scenario, &app, &mut market);
  protocol::deposit::deposit<MainMarket, ETH>(&app, &mut market, &obligation_owner_cap, eth_coin, &clock, scenario.ctx());
  protocol::deposit::deposit<MainMarket, USDT>(&app, &mut market, &obligation_owner_cap, usdt_coin, &clock, scenario.ctx());

  x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
  x_oracle.update_price<USDT>( &clock, oracle_t::calc_scaled_price(1, 0)); // $1
  x_oracle.update_price<ETH>( &clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

  // collateral weighted usd: 1300, debt: 1300
  scenario.next_tx(borrower);
  let borrow_amount = 1300 * 10u64.pow(default_stable_decimal_places());
  let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
  std::unit_test::destroy(borrowed);

  clock.set_for_testing(300000 * 1000);

fun liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
    exchange_rate: Decimal,
    liquidation_incentive: Decimal,
    actual_repay_amount: u64,

    oracle_base_token: x_oracle::x_oracle::BaseToken,
    x_oracle: &XOracle,

    coin_registry: &CoinDecimalsRegistry,
    clock: &Clock,
): u64 {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let price_borrowed = get_spot_price(x_oracle, debt_type, oracle_base_token, clock);
    let price_collateral = get_spot_price(x_oracle, collateral_type, oracle_base_token, clock);

    let actual_repay_amount = float::from(actual_repay_amount);

    let debt_decimals = math::u64::pow10_u64(coin_registry.decimals(debt_type));
    let collateral_decimals = math::u64::pow10_u64(coin_registry.decimals(collateral_type));

    /*
     * Get the exchange rate and calculate the number of collateral tokens to seize:
     *  seizeAmount = (actualRepayAmount + actualRepayAmount * liquidationIncentive) * priceBorrowed / priceCollateral
     *  seizeTokens = seizeAmount / exchangeRate
     */
    let incentivised_borrow = actual_repay_amount.add(actual_repay_amount.mul(
        liquidation_incentive,
    ));
    // ignoreing decimal calculation as they will be cancelled out
    let incentivised_borrow_usd = incentivised_borrow.mul(price_borrowed).div_u64(debt_decimals);
    let seize_collaterals = incentivised_borrow_usd.div(price_collateral).mul_u64(collateral_decimals);

    let seize_ctokens = seize_collaterals.div(exchange_rate);

    assert!(
        seize_ctokens.lt(float::from(std::u64::max_value!())),
        error::invariant_seize_tokens_crazy_big(),
    );

    // only take the tecnnically possible amount
    seize_ctokens.floor()
}

